document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("wallpaper-form"),t=document.getElementById("wallpaper-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const a=parseFloat(document.getElementById("wallpaper-wall-area").value),l=parseFloat(document.getElementById("wallpaper-roll-length").value),n=parseFloat(document.getElementById("wallpaper-roll-width").value),r=parseFloat(document.getElementById("wallpaper-pattern").value);if(a<=0||l<=0||n<=0)return t.textContent="Please enter all parameters with positive values.",void 0;const o=l*(n/12),p=a*(1+r/100),s=Math.ceil(p/o),d=s*o,i=d-a;let c="";switch(r){case 5:c="No pattern/Random";break;case 12:c="Straight match";break;case 20:c="Drop match";break;case 25:c="Large repeat";break;default:c="Custom pattern"}t.innerHTML=`\n        <div class="result-section">\n          <h4>Wallpaper Needed:</h4>\n          <p><strong>${s} rolls</strong> required</p>\n          <p>Wall area: ${a} sq ft</p>\n          <p>Total coverage: ${d.toFixed(1)} sq ft</p>\n        </div>\n        <div class="result-details">\n          <h4>Roll Specifications:</h4>\n          <p>Roll size: ${n}" × ${l}' (${o.toFixed(1)} sq ft each)</p>\n          <p>Pattern type: ${c}</p>\n          <p>Waste allowance: ${r}% (${i.toFixed(1)} sq ft)</p>\n        </div>\n        <div class="result-tips">\n          <p><em>🎨 Order all rolls from the same dye lot for color consistency</em></p>\n          <p><em>📏 Keep one extra roll for future repairs or touch-ups</em></p>\n          <p><em>🔄 Consider pattern direction when ordering</em></p>\n        </div>\n      `})});